 @Autowired Db db;@Autowired MockMvc mvc;@Autowired IngestionService ingestion;@Autowired PublicationService pubs;@Autowired QueryService query;@Autowired ReviewService review;@Autowired WorkbookCodec codec;@Autowired ExportService exports;
 final Authentication aa=new UsernamePasswordAuthenticationToken("aa",null,List.of(new SimpleGrantedAuthority("ROLE_AA")));
 static Map<String,Object> auth(String id,String user){return map("employeeId",user,"userName","测试员工","department","测试部门","personKind",user.equals("L00566785")?"IT人员":"业务人员","employmentClass",user.equals("L00566785")?"雇员":"非雇员","userNamespace","employee","permissionName","测试角色","roleType","业务管理权限","permissionType","业务权限","description","测试功能","startAt","2026-01-01","expiresAt","2027-01-01","authorizationId",id,"application","测试应用","appId","APP1","tenantId","T1","sourceSystem","iAuth");}
 static Map<String,Object> point(){return map("roleName","管理角色","roleType","系统管理权限","setName","业务权限集","pointName","编辑业务数据","pointId","000001","subtype","业务操作","application","测试应用","appId","APP1","tenantId","T1","sourceSystem","iAuth");}
 byte[] fixture(boolean raw,boolean risks,boolean matrix,boolean empty)throws Exception {try(Workbook b=new XSSFWorkbook();ByteArrayOutputStream out=new ByteArrayOutputStream()){
  if(raw){sheet(b,"AUTH",List.of(auth("000001","L00566785"),auth("000002","ZWX933268")));}
  if(risks){List<Map<String,Object>> list=new ArrayList<>();if(!empty){for(String code:List.of("1","3")){var f=auth("000001","L00566785");f.putAll(map("ruleCode",code,"risk","高","workflow","待核实","violation","测试风险","evidence","测试依据","advice","核实职责"));list.add(f);}}sheet(b,"USER_RISK",list);}
  if(matrix){sheet(b,"POINT",List.of(point()));var f=point();f.putAll(map("ruleCode","8a","risk","高","workflow","待核实","confidence",0.9,"violation","测试矩阵冲突","evidence","规则依据"));sheet(b,"MATRIX_RISK",List.of(f));}b.createSheet("可忽略的辅助统计").createRow(0).createCell(0).setCellValue("辅助内容");b.write(out);return out.toByteArray();}}
 void sheet(Workbook b,String type,List<Map<String,Object>> values){Sheet s=b.createSheet(WorkbookCodec.SHEETS.get(type));List<String> fields=Fields.columns(type);Row h=s.createRow(0);for(int i=0;i<fields.size();i++)h.createCell(i).setCellValue(Fields.label(fields.get(i)));int n=1;for(var value:values){Row r=s.createRow(n++);for(int i=0;i<fields.size();i++){Object v=value.get(fields.get(i));if(v instanceof Number num)r.createCell(i).setCellValue(num.doubleValue());else r.createCell(i).setCellValue(v==null?"":String.valueOf(v));}}}
 Map<String,Object> upload(String product,byte[] bytes)throws Exception {var j=ingestion.upload(aa,product,new MockMultipartFile("file","report.xlsx","application/octet-stream",bytes),"auto","FULL","FULL","2026-10-16T18:30:00+08:00",id());String key=str(j,"id");for(int i=0;i<400;i++){ingestion.run();j=ingestion.job(aa,key);if(!List.of("QUEUED","RUNNING").contains(str(j,"status")))break;Thread.sleep(25);}assertEquals("VALIDATED",j.get("status"),String.valueOf(j));return j;}
 String snap(){return str(query.snapshot(aa),"id");}
 Map<String,Object> input(String snapshot,String p,String kind){return map("snapshotId",snapshot,"productId",p,"kind",kind,"page",1,"pageSize",100);}
 @SuppressWarnings("unchecked") List<Map<String,Object>> rows(Map<String,Object> result){return (List<Map<String,Object>>)result.get("rows");}
 void assertStatus(int code,Runnable work){ApiError e=assertThrows(ApiError.class,work::run);assertEquals(code,e.status,e.getMessage());}
 @Test @Order(1) void authenticationScopeAndCsrf()throws Exception{
  mvc.perform(get("/api/me")).andExpect(status().isUnauthorized());
  mvc.perform(get("/api/me").with(httpBasic("aa","wrong"))).andExpect(status().isUnauthorized());
  mvc.perform(get("/api/me").with(httpBasic("aa","aa-demo-2026"))).andExpect(status().isOk()).andExpect(jsonPath("$.canPublish").value(true));
  var tokenResponse=mvc.perform(get("/api/csrf").with(httpBasic("aa","aa-demo-2026"))).andExpect(status().isOk()).andReturn().getResponse();var token=db.decode(tokenResponse.getContentAsString());var pageResponse=mvc.perform(get("/").with(httpBasic("aa","aa-demo-2026")).cookie(tokenResponse.getCookie("XSRF-TOKEN"))).andExpect(status().isOk()).andReturn().getResponse();assertTrue(java.util.Arrays.stream(pageResponse.getCookies()).noneMatch(c->c.getName().equals("XSRF-TOKEN")&&c.getMaxAge()==0));mvc.perform(post("/api/snapshots").with(httpBasic("aa","aa-demo-2026")).cookie(tokenResponse.getCookie("XSRF-TOKEN")).header(str(token,"headerName"),str(token,"token"))).andExpect(status().isOk());
  mvc.perform(post("/api/snapshots").with(user("aa").roles("AA"))).andExpect(status().isForbidden());
  mvc.perform(post("/api/products/P06/drafts").with(user("leader").roles("LEADER")).with(csrf()).contentType("application/json").content("{\"kind\":\"user\"}")).andExpect(status().isForbidden());
  mvc.perform(get("/api/products/P01/releases").with(user("product").roles("PRODUCT"))).andExpect(status().isNotFound());
  mvc.perform(post("/api/snapshots").with(user("platform").roles("PLATFORM")).with(csrf())).andExpect(status().isForbidden());
 }
 @Test @Order(2) void importEditPublicationSnapshotsAndRollback()throws Exception {
  var job=upload("P06",fixture(true,true,true,false));assertNull(pubs.publication("P06").get("releaseId"));String draft=str(job,"draftId");var first=pubs.publish(aa,draft,"1",id(),map("reason","首次发布","allowEmpty",false));String initialId=str(first,"id"),initialMatrix=str(first,"matrixDatasetId"),s0=snap();var users=query.query(aa,input(s0,"P06","user"),false);assertEquals(2L,users.get("total"));assertEquals(1L,query.query(aa,input(s0,"P06","matrix"),false).get("total"));var finding=rows(users).get(0);var trace=query.trace(aa,str(finding,"recordId"),s0,false,"");assertNotNull(trace.get("raw"));assertEquals("LINKED",trace.get("linkStatus"));
  var edit=pubs.createDraft(aa,"P06",List.of("user"));var target=review.findDraftRecord(aa,str(edit,"id"),str(finding,"id"),"user",false);var raw=(Map<String,Object>)target.get("source");var result=review.editSource(aa,str(edit,"id"),str(raw,"id"),"user","1",map("reason","核实有效期","changes",map("expiresAt","2028-01-01")));assertEquals(2L,result.get("affected"));assertStatus(412,()->review.editSource(aa,str(edit,"id"),str(raw,"id"),"user","1",map("reason","并发编辑","changes",map("expiresAt","2029-01-01"))));var second=pubs.publish(aa,str(edit,"id"),"2",id(),map("reason","发布原始副本修订","allowEmpty",false));assertEquals(initialMatrix,second.get("matrixDatasetId"));assertEquals(2L,query.query(aa,input(s0,"P06","user"),false).get("total"));String s1=snap();var changed=rows(query.query(aa,input(s1,"P06","user"),false)).get(0);var evidence=query.trace(aa,str(changed,"id"),s1,false,"");assertEquals("2027-01-01",((Map<?,?>)evidence.get("auditedRaw")).get("expiresAt"));assertEquals("2028-01-01",((Map<?,?>)evidence.get("raw")).get("expiresAt"));assertEquals("待复核",evidence.get("workflow"));
  var correction=pubs.createDraft(aa,"P06",List.of("user"));var c=review.findDraftRecord(aa,str(correction,"id"),str(changed,"id"),"user",false);var cf=(Map<String,Object>)c.get("finding");review.editFinding(aa,str(correction,"id"),str(cf,"id"),"1",map("reason","核实为误报","changes",map("workflow","已确认误报")));pubs.publish(aa,str(correction,"id"),"2",id(),map("reason","发布误报修正","allowEmpty",false));String s2=snap();assertEquals(1L,query.query(aa,input(s2,"P06","user"),false).get("total"));var including=input(s2,"P06","user");including.put("includeFalsePositive",true);assertEquals(2L,query.query(aa,including,false).get("total"));assertEquals(2L,query.query(aa,input(s1,"P06","user"),false).get("total"));
  var d1=pubs.createDraft(aa,"P06",List.of("matrix"));var d2=pubs.createDraft(aa,"P06",List.of("matrix"));String key=id();var one=pubs.publish(aa,str(d1,"id"),"1",key,map("reason","并发发布一","allowEmpty",false));assertEquals(one.get("id"),pubs.publish(aa,str(d1,"id"),"1",key,map("reason","并发发布一","allowEmpty",false)).get("id"));assertStatus(409,()->pubs.publish(aa,str(d1,"id"),"1",key,map("reason","改变请求","allowEmpty",false)));assertStatus(412,()->pubs.publish(aa,str(d2,"id"),"1",id(),map("reason","并发发布二","allowEmpty",false)));
  var rolled=pubs.rollback(aa,"P06",initialId,str(pubs.publication("P06"),"revision"),"恢复首次审查结果");assertNotEquals(initialId,rolled.get("id"));assertEquals(first.get("userDatasetId"),rolled.get("userDatasetId"));assertEquals(2L,query.query(aa,input(snap(),"P06","user"),false).get("total"));
  var zero=upload("P06",fixture(false,true,false,true));String zd=str(zero,"draftId");assertStatus(422,()->pubs.publish(aa,zd,"1",id(),map("reason","完整空清单","allowEmpty",false)));pubs.publish(aa,zd,"1",id(),map("reason","确认完整空清单","allowEmpty",true));String sz=snap();assertEquals(0L,query.query(aa,input(sz,"P06","user"),false).get("total"));assertEquals(1L,query.query(aa,input(sz,"P06","matrix"),false).get("total"));assertEquals(2L,query.query(aa,input(sz,"P06","user"),true).get("total"));var ds=db.one("SELECT raw_as_of FROM review_dataset WHERE id=:id",Map.of("id",pubs.release(str(pubs.publication("P06"),"releaseId")).get("userDatasetId")));assertEquals("2026-10-16T18:30:00+08:00",ds.get("rawAsOf"));
 }
 @Test @Order(3) void parserRejectsBadRowsAndKeepsIds()throws Exception {
  Path p=Files.createTempFile("review-valid-",".xlsx");Files.write(p,fixture(true,true,true,false));var good=codec.parse(p,"auto",Fields.PRODUCT_NAMES[5],()->{});assertEquals(0,good.errorCount);assertEquals("000001",good.data.get("AUTH").get(0).get("authorizationId"));assertEquals("000001",good.data.get("POINT").get(0).get("pointId"));assertEquals(1,good.ignored.size());Files.delete(p);
  try(Workbook b=new XSSFWorkbook();ByteArrayOutputStream out=new ByteArrayOutputStream()){var invalid=auth("A","L00566785");invalid.put("expiresAt","2026-02-30");sheet(b,"AUTH",List.of(invalid));b.write(out);Path bad=Files.createTempFile("review-invalid-",".xlsx");Files.write(bad,out.toByteArray());assertTrue(codec.parse(bad,"auto",Fields.PRODUCT_NAMES[5],()->{}).errorCount>0);Files.delete(bad);}
  try(Workbook b=new XSSFWorkbook();ByteArrayOutputStream out=new ByteArrayOutputStream()){var f=auth("A","L00566785");f.putAll(map("ruleCode","1","risk","高"));sheet(b,"USER_RISK",List.of(f,f));b.write(out);Path bad=Files.createTempFile("review-duplicate-",".xlsx");Files.write(bad,out.toByteArray());assertTrue(codec.parse(bad,"auto",Fields.PRODUCT_NAMES[5],()->{}).errors.stream().anyMatch(e->str(e,"message").contains("重复")));Files.delete(bad);}
  try(Workbook b=new XSSFWorkbook();ByteArrayOutputStream out=new ByteArrayOutputStream()){sheet(b,"AUTH",List.of(auth("A","L00566785")));b.getSheetAt(0).getRow(1).getCell(0).setCellFormula("1+1");b.write(out);Path bad=Files.createTempFile("review-formula-",".xlsx");Files.write(bad,out.toByteArray());assertTrue(codec.parse(bad,"auto",Fields.PRODUCT_NAMES[5],()->{}).errors.stream().anyMatch(e->str(e,"message").contains("公式")));Files.delete(bad);}
  assertNotEquals(Fields.key(auth("A","L00566785"),"user"),Fields.key(new HashMap<>(auth("A","L00566785")){{put("appId","OTHER");}},"user"));
 }
 @Test @Order(4) void distinctUsersAndSafeFilters()throws Exception {
  var j=upload("P01",fixture(true,true,false,false));pubs.publish(aa,str(j,"draftId"),"1",id(),map("reason","第二产品相同人员","allowEmpty",false));String s=snap();var d=query.dashboard(aa,s);var totals=(Map<?,?>)d.get("overall");assertEquals(2L,totals.get("users"));assertEquals(4L,totals.get("authorizations"));assertEquals("PARTIAL",totals.get("rawCoverage"));assertEquals(1L,totals.get("it"));assertEquals(1L,totals.get("external"));var q=input(s,"P01","user");q.put("filters",List.of(map("field","employeeId","op","eq","value","L00566785")));assertEquals(2L,query.query(aa,q,false).get("total"));q.put("filters",List.of(map("field","id) OR 1=1 --","op","eq","value","x")));assertStatus(422,()->query.query(aa,q,false));
 }
 @Test @Order(5) void exportContainsBothChainsAndVersionMetadata()throws Exception {
  String s=snap();var q=input(s,"P06","user");q.put("allKinds",true);String exportKey=id();var j=exports.create(aa,q,exportKey);assertEquals(j.get("id"),exports.create(aa,q,exportKey).get("id"));var conflicting=new LinkedHashMap<>(q);conflicting.put("q","different");assertStatus(409,()->exports.create(aa,conflicting,exportKey));for(int i=0;i<300;i++){exports.run();j=exports.get(aa,str(j,"id"));if(!List.of("QUEUED","RUNNING").contains(str(j,"status")))break;Thread.sleep(25);}assertEquals("SUCCEEDED",j.get("status"),String.valueOf(j));String job=str(j,"id");byte[] bytes=mvc.perform(get("/api/export-jobs/"+job+"/file").with(user("aa").roles("AA"))).andExpect(status().isOk()).andReturn().getResponse().getContentAsByteArray();try(Workbook b=new XSSFWorkbook(new ByteArrayInputStream(bytes))){assertNotNull(b.getSheet("用户角色风险"));assertNotNull(b.getSheet("权限矩阵风险"));assertTrue(b.getSheet("导出说明").getRow(0).getCell(0).getStringCellValue().contains(s));}mvc.perform(get("/api/export-jobs/"+job+"/file").with(user("leader").roles("LEADER"))).andExpect(status().isNotFound());
 }
 @Test @Order(6) void expiredLeaseRecoversAndBadImportDoesNotPublish()throws Exception {
  var original=upload("P02",fixture(true,true,false,false));var clone=db.one("SELECT * FROM import_job WHERE id=:id",Map.of("id",original.get("id")));clone.putAll(map("id",id(),"draftId",null,"status","RUNNING","leaseOwner","expired-worker","leaseUntil","2020-01-01T00:00:00Z","attempts",1,"requestKey",id()));db.insert("import_job",clone);String recoverId=str(clone,"id");Map<String,Object> recovered=null;for(int i=0;i<400;i++){ingestion.run();recovered=ingestion.job(aa,recoverId);if(str(recovered,"status").equals("VALIDATED"))break;Thread.sleep(25);}assertEquals("VALIDATED",recovered.get("status"));assertEquals(2,num(recovered,"attempts"));assertNull(pubs.publication("P02").get("releaseId"));
  byte[] bad;try(Workbook b=new XSSFWorkbook();ByteArrayOutputStream out=new ByteArrayOutputStream()){var row=auth("A","L00566785");row.put("expiresAt","2026-02-30");sheet(b,"AUTH",List.of(row));b.write(out);bad=out.toByteArray();}var j=ingestion.upload(aa,"P03",new MockMultipartFile("file","bad.xlsx","application/octet-stream",bad),"auto","FULL","FULL","2026-10-16T18:30:00+08:00",id());for(int i=0;i<300;i++){ingestion.run();j=ingestion.job(aa,str(j,"id"));if(str(j,"status").equals("FAILED"))break;Thread.sleep(25);}assertEquals("FAILED",j.get("status"));assertNull(pubs.publication("P03").get("releaseId"));
  Path sparse=Files.createTempFile("review-sparse-",".xlsx");try(Workbook b=new XSSFWorkbook();OutputStream out=Files.newOutputStream(sparse)){sheet(b,"AUTH",List.of(auth("000001","L00566785")));b.getSheetAt(0).createRow(1000000);b.write(out);}var parsed=codec.parse(sparse,"auto",Fields.PRODUCT_NAMES[2],()->{});assertEquals(0,parsed.errorCount);assertEquals(1,parsed.data.get("AUTH").size());Files.delete(sparse);
  var riskOnly=upload("P04",fixture(false,true,false,false));pubs.publish(aa,str(riskOnly,"draftId"),"1",id(),map("reason","风险清单先行","allowEmpty",false));var products=(List<Map<String,Object>>)query.dashboard(aa,snap()).get("products");var p=products.stream().filter(x->str(x,"id").equals("P04")).findFirst().orElseThrow();assertNull(p.get("authorizations"));assertNull(p.get("userCount"));assertEquals(2L,rows(query.query(aa,input(snap(),"P04","user"),false)).stream().filter(x->str(x,"linkStatus").equals("UNLINKED")).count());
 }

